// openStore opens a Store on a fresh temp SQLite file and closes it on cleanup.
func openStore(t *testing.T) *Store {
	t.Helper()
	dsn := filepath.Join(t.TempDir(), "test.db")
	s, err := Open(context.Background(), dsn)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })
	return s
}

// TestOpen covers B1 (WAL + full schema migration) and B7 (Open is idempotent:
// re-running migrations on an existing database does not error or duplicate).
func TestOpen(t *testing.T) {
	t.Run("fresh", func(t *testing.T) {
		s := openStore(t)
		var mode string
		if err := s.db.QueryRowContext(context.Background(), "PRAGMA journal_mode").Scan(&mode); err != nil {
			t.Fatalf("read journal mode: %v", err)
		}
		if mode != "wal" {
			t.Fatalf("journal_mode = %q, want wal", mode)
		}
		for _, table := range []string{
			"modules", "plugins", "libraries", "items", "drafts",
			"scan_jobs", "enrichment_failures", "playback_progress",
			"pairing_requests", "device_tokens",
		} {
			var name string
			err := s.db.QueryRowContext(context.Background(),
				"SELECT name FROM sqlite_master WHERE type='table' AND name=?", table).Scan(&name)
			if err != nil {
				t.Fatalf("missing §9.1 table %q: %v", table, err)
			}
		}
	})

	t.Run("reopen_idempotent", func(t *testing.T) {
		dsn := filepath.Join(t.TempDir(), "test.db")
		s1, err := Open(context.Background(), dsn)
		if err != nil {
			t.Fatalf("first Open: %v", err)
		}
		if err := s1.Close(); err != nil {
			t.Fatalf("first Close: %v", err)
		}
		s2, err := Open(context.Background(), dsn) // re-runs migrations on existing DB
		if err != nil {
			t.Fatalf("second Open (idempotent migrations): %v", err)
		}
		t.Cleanup(func() { _ = s2.Close() })
	})

	// busy_timeout (D-T05-2): set per-connection via the DSN so every pooled
	// connection inherits it — the root-cause fix for the concurrent-write
	// "database is locked" errors the async worker pool introduces. Asserted on
	// an arbitrary pool connection (QueryRowContext may use any), which proves it
	// is set pool-wide, not just on the migration connection.
	t.Run("busy_timeout_set", func(t *testing.T) {
		s := openStore(t)
		var bt int
		if err := s.db.QueryRowContext(context.Background(), "PRAGMA busy_timeout").Scan(&bt); err != nil {
			t.Fatalf("read busy_timeout: %v", err)
		}
		if bt != 5000 {
			t.Fatalf("busy_timeout = %d, want 5000 (per-connection, set via DSN)", bt)
		}
	})
}

// TestStore_Library covers B2 (Library type + CreateLibrary/GetLibrary) and the
// not-found error path.
func TestStore_Library(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	t.Run("create_get_roundtrip", func(t *testing.T) {
		id, err := s.CreateLibrary(ctx, "tv", "/data/tv", "TV Series")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		if id <= 0 {
			t.Fatalf("CreateLibrary id = %d, want > 0", id)
		}
		got, err := s.GetLibrary(ctx, id)
		if err != nil {
			t.Fatalf("GetLibrary: %v", err)
		}
		if got.ID != id || got.ModuleID != "tv" || got.RootPath != "/data/tv" ||
			got.DisplayName != "TV Series" || got.CreatedAt.IsZero() {
			t.Fatalf("GetLibrary = %+v, want id=%d module=tv root=/data/tv name=TV Series nonzero time",
				got, id)
		}
	})

	t.Run("not_found", func(t *testing.T) {
		if _, err := s.GetLibrary(ctx, 99999); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetLibrary missing = %v, want sql.ErrNoRows", err)
		}
	})

	// list_ordering_and_empty covers ListLibraries (T02 / AC-3): an empty
	// table returns a non-nil empty slice ({"items":[]} not {"items":null}),
	// and inserting N libraries in non-id-sorted order returns them id ASC
	// with every field round-tripped. Same assertion shape as create_get.
	t.Run("list_ordering_and_empty", func(t *testing.T) {
		emptyStore := openStore(t)
		got, err := emptyStore.ListLibraries(ctx)
		if err != nil {
			t.Fatalf("ListLibraries empty: %v", err)
		}
		if got == nil {
			t.Fatalf("ListLibraries empty = nil, want non-nil empty slice (INV-empty-not-nil)")
		}
		if len(got) != 0 {
			t.Fatalf("ListLibraries empty = %d rows, want 0", len(got))
		}

		// Insert 3 libraries in non-sorted order (module_id / root_path
		// intentionally out of band); ListLibraries must return them id ASC.
		// Uses a fresh store so the only rows are the 3 seeds (assertion is
		// over the full returned slice, not a subset).
		listStore := openStore(t)
		seeds := []struct {
			moduleID, rootPath, displayName string
		}{
			{"image", "/data/img", "Images"},
			{"movie", "/data/movies", "Films"},
			{"tv", "/data/tv-list", "TV List"},
		}
		var ids []int64
		for _, seed := range seeds {
			id, err := listStore.CreateLibrary(ctx, seed.moduleID, seed.rootPath, seed.displayName)
			if err != nil {
				t.Fatalf("CreateLibrary %q: %v", seed.displayName, err)
			}
			ids = append(ids, id)
		}
		list, err := listStore.ListLibraries(ctx)
		if err != nil {
			t.Fatalf("ListLibraries: %v", err)
		}
		if len(list) != len(seeds) {
			t.Fatalf("ListLibraries = %d rows, want %d", len(list), len(seeds))
		}
		// Ascending id: each returned id strictly greater than the previous.
		for i := 1; i < len(list); i++ {
			if list[i].ID <= list[i-1].ID {
				t.Fatalf("ListLibraries not id ASC at %d: %d <= %d", i, list[i].ID, list[i-1].ID)
			}
		}
		// Each seeded library round-trips (module/root/name non-empty; time set).
		byID := make(map[int64]Library, len(list))
		for _, l := range list {
			byID[l.ID] = l
		}
		for i, seed := range seeds {
			l, ok := byID[ids[i]]
			if !ok {
				t.Fatalf("seeded id %d missing from ListLibraries", ids[i])
			}
			if l.ModuleID != seed.moduleID || l.RootPath != seed.rootPath ||
				l.DisplayName != seed.displayName || l.CreatedAt.IsZero() {
				t.Fatalf("library id=%d = %+v, want module=%s root=%s name=%s nonzero time",
					ids[i], l, seed.moduleID, seed.rootPath, seed.displayName)
			}
		}
	})
}

// TestStore_Items covers B2 (Item + GetItem/PutItem), B3 (PutItem upsert by
// file_id is idempotent: two puts = one row), and B6 (document round-trips
// arbitrary JSON incl. Cyrillic + deeply-nested ffprobe; the generated
// display_title column returns the json_extract-ed value). Table-driven over
// document fixtures.
func TestStore_Items(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	fixtures := []struct {
		name      string
		document  string // raw JSON stored opaque in the document column
		wantTitle string // expected generated display_title (json_extract)
	}{
		{
			name:      "cyrillic_title",
			document:  `{"_view":{"title":{"value":"Сериалы"}}}`,
			wantTitle: "Сериалы",
		},
		{
			name: "nested_ffprobe",
			document: `{"ffprobe":{"format":{"duration":"1421.50",` +
				`"tags":{"title":"Breaking Bad"}},"streams":[{"codec_type":"video"}]},` +
				`"_view":{"title":{"value":"Breaking Bad"}}}`,
			wantTitle: "Breaking Bad",
		},
		{
			name: "cyrillic_and_nested",
			document: `{"ffprobe":{"format":{"duration":"1850.0",` +
				`"tags":{"title":"Игра Престолов"}}},"identifiers":{"tmdb_id":1399},` +
				`"_view":{"title":{"value":"Игра Престолов"}}}`,
			wantTitle: "Игра Престолов",
		},
	}

	for _, tc := range fixtures {
		t.Run(tc.name, func(t *testing.T) {
			libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), tc.name), tc.name)
			if err != nil {
				t.Fatalf("CreateLibrary: %v", err)
			}
			doc := json.RawMessage(tc.document)
			it := Item{
				ID: "01HZZ" + tc.name, ModuleID: "tv", LibraryID: libID,
				FileID: "fid-" + tc.name, RelativePath: tc.name + ".mkv",
				MediaType: "tv", Document: doc, SchemaVersion: 1,
			}

			// First PutItem.
			if err := s.PutItem(ctx, it); err != nil {
				t.Fatalf("PutItem #1: %v", err)
			}
			// Second PutItem, same file_id — must upsert, not duplicate (B3).
			if err := s.PutItem(ctx, it); err != nil {
				t.Fatalf("PutItem #2: %v", err)
			}

			// Idempotency: exactly one row for this library (public API, no db reach-in).
			items, err := s.QueryItems(ctx, libID, "", 100, 0)
			if err != nil {
				t.Fatalf("QueryItems: %v", err)
			}
			if len(items) != 1 {
				t.Fatalf("after double PutItem, QueryItems = %d rows, want 1 (idempotent re-scan)", len(items))
			}

			// GetItem round-trips the opaque document byte-for-byte (Cyrillic + nested).
			got, err := s.GetItem(ctx, it.ID)
			if err != nil {
				t.Fatalf("GetItem: %v", err)
			}
			if !bytes.Equal(got.Document, doc) {
				t.Fatalf("document round-trip mismatch:\n got:  %s\n want: %s", got.Document, doc)
			}
			if got.FileID != it.FileID || got.MediaType != "tv" || got.SchemaVersion != 1 {
				t.Fatalf("GetItem fields = %+v", got)
			}

			// Generated column: display_title holds the json_extract-ed value (B6).
			var title sql.NullString
			if err := s.db.QueryRowContext(ctx,
				"SELECT display_title FROM items WHERE file_id = ?", it.FileID).Scan(&title); err != nil {
				t.Fatalf("select display_title: %v", err)
			}
			if !title.Valid || title.String != tc.wantTitle {
				t.Fatalf("display_title = %q (valid=%v), want %q", title.String, title.Valid, tc.wantTitle)
			}
		})
	}
}

// TestStore_QueryItems covers B4 (filter by library_id with LIMIT/OFFSET).
func TestStore_QueryItems(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	libID, err := s.CreateLibrary(ctx, "tv", "/data/tv2", "TV2")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	const total = 3
	for i := 0; i < total; i++ {
		it := Item{
			ID: "01Q" + string(rune('A'+i)), ModuleID: "tv", LibraryID: libID,
			FileID: "fid-q" + string(rune('A'+i)), RelativePath: "f" + string(rune('A'+i)),
			MediaType: "tv", Document: json.RawMessage(`{}`), SchemaVersion: 1,
		}
		if err := s.PutItem(ctx, it); err != nil {
			t.Fatalf("PutItem %d: %v", i, err)
		}
	}
	// An item in a different library must NOT appear.
	other, err := s.CreateLibrary(ctx, "tv", "/data/other", "Other")
	if err != nil {
		t.Fatalf("CreateLibrary other: %v", err)
	}
	if err := s.PutItem(ctx, Item{
		ID: "01OTHER", ModuleID: "tv", LibraryID: other, FileID: "fid-other",
		RelativePath: "x", MediaType: "tv", Document: json.RawMessage(`{}`), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem other: %v", err)
	}

	cases := []struct {
		name   string
		limit  int
		offset int
		want   int
	}{
		{"all", 100, 0, total},
		{"first_page", 2, 0, 2},
		{"second_page", 2, 2, 1},
		{"beyond_end", 2, 3, 0},
		{"zero_limit_returns_none", 0, 0, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := s.QueryItems(ctx, libID, "", tc.limit, tc.offset)
			if err != nil {
				t.Fatalf("QueryItems(%d,%d): %v", tc.limit, tc.offset, err)
			}
			if len(got) != tc.want {
				t.Fatalf("QueryItems(lib=%d, limit=%d, offset=%d) = %d rows, want %d",
					libID, tc.limit, tc.offset, len(got), tc.want)
			}
		})
	}
}

// TestStore_StatusColumn_Default covers T04 B1 (fresh DB): the items.status
// column exists with DEFAULT 'new' (the AC-3/AC-7 probe). A raw insert omitting
// status proves the column exists; the read-back proves the default is 'new'.
// (Behavioral assertion: SQLite's PRAGMA dflt_value echoes the literal "'new'"
// text; reading the applied value is the robust check.)
func TestStore_StatusColumn_Default(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	if _, err := s.db.ExecContext(ctx,
		`INSERT INTO items (id, module_id, library_id, file_id, relative_path, media_type, document, schema_version, created_at, updated_at)
		 VALUES ('d', 'tv', 1, 'fd', 'r', 'tv', '{}', 1, '1970-01-01T00:00:00Z', '1970-01-01T00:00:00Z')`); err != nil {
		t.Fatalf("raw insert (status omitted) failed -- column missing?: %v", err)
	}
	var status string
	if err := s.db.QueryRowContext(ctx, "SELECT status FROM items WHERE id = 'd'").Scan(&status); err != nil {
		t.Fatalf("select status: %v", err)
	}
	if status != "new" {
		t.Fatalf("status default = %q, want 'new'", status)
	}
}

// TestStore_ItemsStatus_RoundTrip covers T04 B2/B3: PutItem writes status (and
// defaults an empty Status to 'new'); GetItem/QueryItems read it back; the
// QueryItems status filter selects only matching rows while empty returns all.
func TestStore_ItemsStatus_RoundTrip(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", "/data/status", "StatusLib")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	if err := s.PutItem(ctx, Item{
		ID: "en1", ModuleID: "tv", LibraryID: libID, FileID: "fe1",
		RelativePath: "e1", MediaType: "tv", Document: json.RawMessage(`{}`),
		SchemaVersion: 1, Status: "enriched",
	}); err != nil {
		t.Fatalf("PutItem enriched: %v", err)
	}
	if err := s.PutItem(ctx, Item{
		ID: "nw1", ModuleID: "tv", LibraryID: libID, FileID: "fn1",
		RelativePath: "n1", MediaType: "tv", Document: json.RawMessage(`{}`),
		SchemaVersion: 1, // Status omitted -> defaultStatus 'new'
	}); err != nil {
		t.Fatalf("PutItem new: %v", err)
	}
	en, err := s.GetItem(ctx, "en1")
	if err != nil {
		t.Fatalf("GetItem en1: %v", err)
	}
	if en.Status != "enriched" {
		t.Fatalf("GetItem(en1).Status = %q, want 'enriched'", en.Status)
	}
	nw, _ := s.GetItem(ctx, "nw1")
	if nw.Status != "new" {
		t.Fatalf("GetItem(nw1).Status = %q, want 'new' (PutItem default)", nw.Status)
	}
	only, err := s.QueryItems(ctx, libID, "enriched", 100, 0)
	if err != nil {
		t.Fatalf("QueryItems(enriched): %v", err)
	}
	if len(only) != 1 || only[0].ID != "en1" {
		t.Fatalf("QueryItems(enriched) = %+v, want [en1]", only)
	}
	all, err := s.QueryItems(ctx, libID, "", 100, 0)
	if err != nil {
		t.Fatalf("QueryItems(all): %v", err)
	}
	if len(all) != 2 {
		t.Fatalf("QueryItems('') = %d items, want 2 (empty status = all)", len(all))
	}
}

// TestStore_ItemsStatus_Migration covers T04 B1/INV-idempotent-migration: a
// pre-status items table (the scan-library shape, simplified) gets the column
// via ensureItemsStatus; the DEFAULT 'new' backfills the pre-existing row; and
// re-running the migration is idempotent. ensureItemsStatus is exercised
// directly because store.Open's full schemaSQL needs the generated columns this
// minimal table omits.
func TestStore_ItemsStatus_Migration(t *testing.T) {
	ctx := context.Background()
	dsn := filepath.Join(t.TempDir(), "prestatus.db")
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		t.Fatalf("sql.Open: %v", err)
	}
	if _, err := db.ExecContext(ctx,
		`CREATE TABLE items (id TEXT PRIMARY KEY, library_id INTEGER NOT NULL, file_id TEXT NOT NULL)`); err != nil {
		t.Fatalf("create pre-status items: %v", err)
	}
	if _, err := db.ExecContext(ctx,
		`INSERT INTO items (id, library_id, file_id) VALUES ('pre', 1, 'f-pre')`); err != nil {
		t.Fatalf("insert pre-status row: %v", err)
	}
	if err := db.Close(); err != nil {
		t.Fatalf("close raw db: %v", err)
	}
	db2, err := sql.Open("sqlite", dsn)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer db2.Close()
	if err := ensureItemsStatus(ctx, db2); err != nil {
		t.Fatalf("ensureItemsStatus on pre-status DB: %v", err)
	}
	var status string
	if err := db2.QueryRowContext(ctx, "SELECT status FROM items WHERE id = 'pre'").Scan(&status); err != nil {
		t.Fatalf("select status after migration: %v", err)
	}
	if status != "new" {
		t.Fatalf("pre-existing row status = %q, want 'new' (ALTER DEFAULT backfill)", status)
	}
	if err := ensureItemsStatus(ctx, db2); err != nil {
		t.Fatalf("ensureItemsStatus re-run (must be idempotent): %v", err)
	}
}

// TestStore_DeleteLibrary covers the cascade contract: deleting a library
// removes the row, its items and series, their identity-keyed control rows
// (progress, parser attachments, title overrides in BOTH id spaces), and the
// library-scope rows (scan jobs, parser chain, source-prefs) — while a
// bystander library sharing the tables keeps every row, and module-scope
// metadata_source_prefs (library_id 0) survive. A second delete of the same
// id is sql.ErrNoRows (the api layer maps it to 404).
func TestStore_DeleteLibrary(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	target, err := s.CreateLibrary(ctx, "serial", "/data/ongoing", "Ongoings")
	if err != nil {
		t.Fatalf("CreateLibrary target: %v", err)
	}
	bystander, err := s.CreateLibrary(ctx, "tv", "/data/tv", "TV")
	if err != nil {
		t.Fatalf("CreateLibrary bystander: %v", err)
	}

	mkItem := func(id, fileID string, lib int64) Item {
		return Item{
			ID: id, ModuleID: "tv", LibraryID: lib, FileID: fileID,
			RelativePath: fileID + ".mkv", MediaType: "video",
			Document:      json.RawMessage(`{"_view":{"title":{"value":"` + id + `"}}}`),
			SchemaVersion: 1,
		}
	}
	for _, it := range []Item{mkItem("itm_a1", "f1", target), mkItem("itm_a2", "f2", target), mkItem("itm_b1", "f3", bystander)} {
		if err := s.PutItem(ctx, it); err != nil {
			t.Fatalf("PutItem %s: %v", it.ID, err)
		}
	}
	if err := s.PutSeries(ctx, Series{
		ModuleID: "serial", LibraryID: target, RelativePath: "One Piece",
		Document: json.RawMessage(`{}`), SchemaVersion: 1, Status: "new",
	}); err != nil {
		t.Fatalf("PutSeries: %v", err)
	}
	var serID string
	if err := s.db.QueryRowContext(ctx, "SELECT id FROM series WHERE library_id = ?", target).Scan(&serID); err != nil {
		t.Fatalf("read series id: %v", err)
	}

	// Control rows: per-item ones for BOTH libraries' items, per-series
	// title overrides, and the library-scope tables for both libraries.
	for _, itemID := range []string{"itm_a1", "itm_b1"} {
		if _, err := s.PutProgress(ctx, itemID, 42); err != nil {
			t.Fatalf("PutProgress %s: %v", itemID, err)
		}
	}
	seed := []string{
		`INSERT INTO item_parsers (item_id, plugin_id, position) VALUES ('itm_a1','p1',0),('itm_b1','p1',0)`,
		`INSERT INTO enrichment_failures (item_id, plugin_id, status, reason, attempts, failed_at, next_eligible_at) VALUES ('itm_a1','p1','failed','',1,'t','t')`,
		`INSERT INTO title_overrides (entity_id, title, updated_at) VALUES ('itm_a1','A','t'),('` + serID + `','S','t'),('itm_b1','B','t')`,
		`INSERT INTO scan_jobs (library_id, status, started_at, updated_at) VALUES (` + fmtInt(target) + `,'done','t','t'),(` + fmtInt(bystander) + `,'done','t','t')`,
		`INSERT INTO library_parsers (library_id, plugin_id, position) VALUES (` + fmtInt(target) + `,'p1',0),(` + fmtInt(bystander) + `,'p1',0)`,
		`INSERT INTO metadata_source_prefs (module_id, library_id, plugin_id, enabled, updated_at) VALUES ('tv',` + fmtInt(target) + `,'p1',0,'t'),('tv',0,'p2',1,'t')`,
	}
	for _, q := range seed {
		if _, err := s.db.ExecContext(ctx, q); err != nil {
			t.Fatalf("seed %q: %v", q, err)
		}
	}

	if err := s.DeleteLibrary(ctx, target); err != nil {
		t.Fatalf("DeleteLibrary: %v", err)
	}

	count := func(table, where string, args ...any) int {
		t.Helper()
		var n int
		if err := s.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM "+table+" WHERE "+where, args...).Scan(&n); err != nil {
			t.Fatalf("count %s: %v", table, err)
		}
		return n
	}
	// The target's every row is gone...
	for _, c := range []struct{ table, where string }{
		{"items", "library_id = ?"},
		{"series", "library_id = ?"},
		{"scan_jobs", "library_id = ?"},
		{"library_parsers", "library_id = ?"},
		{"metadata_source_prefs", "library_id = ?"},
		{"playback_progress", "item_id = 'itm_a1'"},
		{"item_parsers", "item_id = 'itm_a1'"},
		{"enrichment_failures", "item_id = 'itm_a1'"},
		{"title_overrides", "entity_id IN ('itm_a1',?)"},
	} {
		var args []any
		if c.where == "library_id = ?" {
			args = append(args, target)
		} else if c.where == "entity_id IN ('itm_a1',?)" {
			args = append(args, serID)
		}
		if n := count(c.table, c.where, args...); n != 0 {
			t.Fatalf("%s after delete = %d rows, want 0", c.table, n)
		}
	}
	// ...the bystander's every row survives, and so does the module-scope pref.
	if n := count("items", "library_id = ?", bystander); n != 1 {
		t.Fatalf("bystander items = %d, want 1", n)
	}
	if n := count("title_overrides", "entity_id = 'itm_b1'"); n != 1 {
		t.Fatalf("bystander title override = %d, want 1", n)
	}
	if n := count("metadata_source_prefs", "library_id = 0"); n != 1 {
		t.Fatalf("module-scope source pref = %d, want 1 (library delete never touches module scope)", n)
	}
	if _, err := s.GetLibrary(ctx, target); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("GetLibrary deleted = %v, want sql.ErrNoRows", err)
	}
	// Second delete of the same id: sql.ErrNoRows (404 at the api layer).
	if err := s.DeleteLibrary(ctx, target); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("DeleteLibrary repeat = %v, want sql.ErrNoRows", err)
	}
}

// fmtInt is the test-local int64→string for building seed SQL literals.
func fmtInt(v int64) string { return strconv.FormatInt(v, 10) }
